import{_ as s,o as r,c as t,ak as i,al as o,am as a,an as n,ao as d,ap as p}from"./chunks/framework.DveU0bjS.js";const v=JSON.parse('{"title":"Gestion des images et des sprites dans Unity","description":"","frontmatter":{},"headers":[],"relativePath":"01_AjouterSprites.md","filePath":"01_AjouterSprites.md","lastUpdated":1769208785000}'),l={name:"01_AjouterSprites.md"};function c(u,e,m,g,h,f){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="gestion-des-images-et-des-sprites-dans-unity" tabindex="-1">Gestion des images et des sprites dans Unity <a class="header-anchor" href="#gestion-des-images-et-des-sprites-dans-unity" aria-label="Permalink to “Gestion des images et des sprites dans Unity”">​</a></h1><p>Les sprites sont des images 2D utilisées dans les jeux vidéo pour représenter des personnages, des objets, des arrière-plans, etc. Unity offre une gestion complète des sprites, permettant de les importer, de les organiser et de les manipuler facilement.</p><h2 id="importation-des-sprites" tabindex="-1">Importation des sprites <a class="header-anchor" href="#importation-des-sprites" aria-label="Permalink to “Importation des sprites”">​</a></h2><p>Vous pouvez simplement glisser-déposer des fichiers image (comme PNG, JPEG, etc.) dans le dossier <code>Assets</code> de votre projet Unity. Unity reconnaît automatiquement ces fichiers comme des sprites. Les fichiers PSD (Photoshop) sont également pris en charge, mais il est recommandé de les convertir en PNG pour une meilleure compatibilité.</p><p>Une fois importés, vous pouvez sélectionner les images dans le dossier <code>Assets</code> et, dans l&#39;inspecteur, définir leur <code>Texture Type</code> sur <code>Sprite (2D and UI)</code> pour les utiliser comme sprites si ce n&#39;est pas déjà fait.</p><p><img src="'+o+'" alt="Propriétés des sprites dans l&#39;inspecteur Unity"></p><p>Les sprites ont les propriétés suivantes dans l&#39;inspecteur Unity :</p><ul><li><strong>Pixels Per Unit</strong> : Définit combien de pixels dans l&#39;image correspondent à une unité Unity. Par défaut, c&#39;est 100 pixels par unité.</li><li><strong>Mesh Type</strong> : Définit la forme du maillage utilisé pour le sprite. Les options sont <code>Full Rect</code> (rectangle complet) ou <code>Tight</code> (maillage ajusté autour du sprite). Cela retire de l&#39;espace vide autour du sprite.</li><li><strong>Pivot</strong> : Définit le point d&#39;ancrage du sprite. Vous pouvez choisir parmi des options prédéfinies ou définir une position personnalisée.</li><li><strong>Filter Mode</strong> : Définit la manière dont le sprite est filtré lorsqu&#39;il est mis à l&#39;échelle. Les options sont <code>Point</code> (pixelisé), <code>Bilinear</code> (lissé) et <code>Trilinear</code> (lissé avec mipmaps). À changer selon le style graphique souhaité.</li><li><strong>Compression</strong> : Permet de compresser la texture pour économiser de l&#39;espace mémoire, avec des options comme <code>None</code>, <code>Low</code>, <code>Medium</code>, et <code>High</code>.</li></ul><h2 id="sprite-editor" tabindex="-1">Sprite Editor <a class="header-anchor" href="#sprite-editor" aria-label="Permalink to “Sprite Editor”">​</a></h2><p>Unity dispose d&#39;un outil appelé <code>Sprite Editor</code> qui permet de découper des images en plusieurs sprites, ce qui est particulièrement utile pour les feuilles de sprites (sprite sheets). Pour accéder au Sprite Editor :</p><ol><li>Sélectionnez l&#39;image dans le dossier <code>Assets</code>.</li><li>Dans l&#39;inspecteur, cliquez sur le bouton <code>Sprite Editor</code>.</li><li>Utilisez les outils disponibles pour découper l&#39;image en plusieurs sprites selon vos besoins. Dans le menu &quot;slice&quot;, vous pouvez choisir entre <code>Automatic</code> (découpe automatique basée sur la transparence) ou <code>Grid By Cell Size</code> / <code>Grid By Cell Count</code> (découpe en grille selon la taille ou le nombre de cellules).</li><li>Cliquez sur <code>Apply</code> pour enregistrer les modifications.</li><li>Une fois découpés, les sprites individuels apparaîtront comme des sous-éléments de l&#39;image dans le dossier <code>Assets</code>, et vous pourrez les utiliser séparément dans votre scène.</li></ol><p><a href="https://docs.unity3d.com/Manual/SpriteEditor.html" target="_blank" rel="noreferrer">Documentation officielle du Sprite Editor</a></p><p><img src="'+a+'" alt="Éditeur de sprites"></p><p><img src="'+n+'" alt="Récupération des sprites individuels"></p><h2 id="utilisation-des-sprites-dans-la-scene-et-sprite-renderer" tabindex="-1">Utilisation des sprites dans la scène et Sprite Renderer <a class="header-anchor" href="#utilisation-des-sprites-dans-la-scene-et-sprite-renderer" aria-label="Permalink to “Utilisation des sprites dans la scène et Sprite Renderer”">​</a></h2><p>Pour utiliser un sprite dans votre scène Unity, il suffit de le glisser-déposer depuis le dossier <code>Assets</code> vers la fenêtre <code>Hierarchy</code> ou directement dans la fenêtre <code>Scene</code>. Cela crée un GameObject avec un composant <code>Sprite Renderer</code> qui affiche le sprite. Le composant <code>Sprite Renderer</code> a plusieurs propriétés que vous pouvez ajuster, telles que la couleur, l&#39;ordre de tri (pour gérer la superposition des sprites), et le matériau.</p><h3 id="mon-sprite-n-apparait-pas-correctement" tabindex="-1">Mon sprite n&#39;apparaît pas correctement... <a class="header-anchor" href="#mon-sprite-n-apparait-pas-correctement" aria-label="Permalink to “Mon sprite n&#39;apparaît pas correctement...”">​</a></h3><p>Pour afficher un sprite devant un autre, vous pouvez ajuster la propriété <code>Order in Layer</code> du composant <code>Sprite Renderer</code>. Un nombre plus élevé signifie que le sprite sera rendu au-dessus des sprites avec des nombres plus bas.</p><p>Les sprites peuvent être assignés à une <strong>couche de tri (<code>SortingLayer</code>)</strong>, qui permet de <strong>gérer l&#39;ordre de rendu des groupes de sprites</strong>. Par exemple, les sprites de fond peuvent être placés dans une couche &quot;Background&quot;, les personnages dans &quot;Characters&quot;, et les objets d&#39;interface dans &quot;UI&quot;. L&#39;ordre de rendu de ces groupes est configurée dans les paramètres du projet (<code>ProjectSettings &gt; Tags and Layers &gt; Sorting Layers</code>).</p><p><img src="'+d+'" alt="SortingLayers"></p><p>Pour retourner un sprite horizontalement ou verticalement, vous pouvez cocher les cases <code>Flip X</code> ou <code>Flip Y</code> dans le composant <code>Sprite Renderer</code>.</p><p><img src="'+p+'" alt="Sprite Renderer dans l&#39;inspecteur Unity"></p>',22)])])}const S=s(l,[["render",c]]);export{v as __pageData,S as default};
